function maxProduct(a) {
  let best = -Infinity;
  for (let i = 0; i < a.length; i++) { let p = 1; for (let j = i; j < a.length; j++) { p *= a[j]; if (p === 0) p = 0; best = Math.max(best, p); } }
  return best;
}
